    // 19. DA
    "\u042F \u0434\u043E\u043B\u0433\u043E \u043D\u0435 \u043C\u043E\u0433\u0443 \u0440\u0435\u0448\u0438\u0442\u044C\u0441\u044F \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0447\u0442\u043E-\u0442\u043E \u043D\u043E\u0432\u043E\u0435, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u0431\u043E\u044E\u0441\u044C \u043E\u0448\u0438\u0431\u0438\u0442\u044C\u0441\u044F",
    // 20. PE
