      interpretation = "\u0423 \u0432\u0430\u0441 \u0432\u044B\u0441\u043E\u043A\u0438\u0435 \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u044B \u0438 \u0437\u0430\u043C\u0435\u0442\u043D\u0430\u044F \u0441\u0430\u043C\u043E\u043A\u0440\u0438\u0442\u0438\u043A\u0430. \u0427\u0430\u0441\u0442\u044C \u0438\u0437 \u044D\u0442\u043E\u0433\u043E \u2014 \u0440\u0435\u0441\u0443\u0440\u0441, \u0447\u0430\u0441\u0442\u044C \u2014 \u043C\u0435\u0448\u0430\u0435\u0442.";
      recommendation = "\u041F\u043E\u043B\u0435\u0437\u043D\u043E \u0440\u0430\u0437\u043B\u0438\u0447\u0430\u0442\u044C \u0437\u0434\u043E\u0440\u043E\u0432\u043E\u0435 \u0441\u0442\u0440\u0435\u043C\u043B\u0435\u043D\u0438\u0435 \u043A \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u0443 \u0438 \u0442\u0440\u0435\u0432\u043E\u0436\u043D\u044B\u0439 \u043F\u0435\u0440\u0444\u0435\u043A\u0446\u0438\u043E\u043D\u0438\u0437\u043C. \u041F\u043E\u043C\u043E\u0433\u0443\u0442 \u041A\u041F\u0422-\u0442\u0435\u0445\u043D\u0438\u043A\u0438 \u0440\u0430\u0431\u043E\u0442\u044B \u0441 \u0443\u0431\u0435\u0436\u0434\u0435\u043D\u0438\u044F\u043C\u0438.";
